#include <stdio.h>

int main(void) {
    int A, L, N;
    scanf("%d %d", &A, &L);
    scanf("%d", &N);

    int best = -1;
    long long bestArea = 0;

    for (int i = 1; i <= N; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);

        if ((X >= A && Y >= L) || (X >= L && Y >= A)) {
            long long area = (long long)X * Y;
            if (best == -1 || area < bestArea) {
                best = i;
                bestArea = area;
            }
        }
    }

    printf("%d\n", best);
    return 0;
}
